import React from "react";
import PropTypes from "prop-types";
import classNames from "classnames";
import { Button } from "@traveloka/soya-components";

import * as style from "./ToggleTooltip.styles";

class ToggleTooltip extends React.Component {
  constructor(props) {
    super(props);

    this._handleClickOutside = this._handleClickOutside.bind(this);
    this._popoverOnClick = this._popoverOnClick.bind(this);

    this.state = {
      show: false,
    };
  }

  static get propTypes() {
    return {
      direction: PropTypes.string,
      theme: PropTypes.string,
    };
  }

  static get THEME() {
    return {
      DEFAULT: "default",
      WHITE: "white",
    };
  }

  componentDidMount() {
    document.addEventListener("mousedown", this._handleClickOutside, false);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this._handleClickOutside, false);
  }

  render() {
    const { theme, direction } = this.props;

    return (
      <div
        className={classNames(style.popover, `${theme}`, {
          [direction]: direction,
        })}
        ref={(node) => (this.node = node)}
      >
        <Button
          iconProps={{ icon: "more-horiz" }}
          variant="white"
          marginRight="sm"
          isOutline={false}
          onClick={this._popoverOnClick}
        />
        <div
          className={classNames("popoverPanelRuleMgmt", {
            ["open"]: this.state.show,
          })}
        >
          {this.props.children}
        </div>
      </div>
    );
  }

  // Event Handlers
  // -------------------------------

  _handleClickOutside(e) {
    if (this.node.contains(e.target)) {
      return;
    }

    this.setState({ show: false });
  }

  _popoverOnClick(event) {
    event.stopPropagation();
    this.setState((previousState, nextProps) => {
      return {
        show: !previousState.show,
      };
    });
  }
}

export default ToggleTooltip;
